import json
import math
import os
import time
import timeit

import numpy as np
import pandas as pd


def setup():
    np.random.seed(42)
    left = pd.DataFrame(
        {
            "key": np.arange(0, 1_000_000, 2),
            "val1": np.ones(500_000, dtype=np.float64),
        }
    )
    right = pd.DataFrame(
        {
            "key": np.arange(500_000, 700_000, 1),
            "val2": np.full(200_000, 2, dtype=np.float64),
        }
    )
    left = left.sort_values("key").reset_index(drop=True)
    right = right.sort_values("key").reset_index(drop=True)
    return (left, right)


def experiment(left, right):
    merged = pd.merge_ordered(left, right, on="key", how="inner")
    return merged


def store_result(result, filename):
    numeric_cols = result.select_dtypes(include=[np.number]).columns
    sums = {col: float(result[col].sum()) for col in numeric_cols}
    result_summary = {"shape": result.shape, "columns": list(result.columns), "sums": sums}
    with open(filename, "w") as f:
        json.dump(result_summary, f)


def load_result(filename):
    if not os.path.exists(filename):
        raise FileNotFoundError(f"Reference result file '{filename}' not found.")
    with open(filename) as f:
        result_summary = json.load(f)
    return result_summary


def check_equivalence(ref_result, current_result):
    curr_shape = current_result.shape
    assert tuple(ref_result["shape"]) == curr_shape, (
        f"Expected shape {ref_result['shape']}, got {curr_shape}"
    )
    curr_columns = list(current_result.columns)
    ref_columns = list(ref_result["columns"])
    assert ref_columns == curr_columns, f"Expected columns {ref_columns}, got {curr_columns}"
    numeric_cols = current_result.select_dtypes(include=[np.number]).columns
    current_sums = {col: float(current_result[col].sum()) for col in numeric_cols}
    for col, ref_sum in ref_result["sums"].items():
        assert col in current_sums, f"Numeric column '{col}' not found in current result."
        curr_sum = current_sums[col]
        if ref_sum == 0:
            assert math.isclose(curr_sum, ref_sum, abs_tol=1e-08), (
                f"Column '{col}' sum mismatch: expected {ref_sum}, got {curr_sum}"
            )
        else:
            assert math.isclose(curr_sum, ref_sum, rel_tol=1e-06), (
                f"Column '{col}' sum mismatch: expected {ref_sum}, got {curr_sum}"
            )


def run_test(eqcheck=False, reference=False, prefix=""):
    left, right = setup()
    result_box = {}
    start = time.perf_counter()
    result_box["result"] = experiment(left, right)
    exec_time = time.perf_counter() - start
    result = result_box["result"]
    filename = f"{prefix}_result.json" if prefix else "/workspace/reference_result.json"
    if reference:
        store_result(result, filename)
    if eqcheck:
        ref_result = load_result(filename)
        check_equivalence(ref_result, result)
    print(
        f"pandas={pd.__version__} time={exec_time:.6f}s shape={result.shape} "
        f"sums={ {c: float(result[c].sum()) for c in result.select_dtypes(include=[np.number]).columns} }"
    )
    return exec_time


if __name__ == "__main__":
    # Warm import/setup outside timing; run once for reference if needed.
    ref = not os.path.exists("/workspace/reference_result.json")
    times = []
    for i in range(5):
        times.append(run_test(eqcheck=not ref, reference=ref and i == 0))
    print("times", [round(t, 6) for t in times], "best", round(min(times), 6))
